package main

import (
	"embed"
	"mime"
	"path"
	"strings"

	"github.com/gofiber/fiber/v3"
	"github.com/open-rails/openrails/billing"
)

// frontendFiles is generated by `pnpm --dir frontend build` and embedded into
// the standalone Go binary. Development uses Vite separately via Taskfile.
//
//go:embed frontend/dist
var frontendFiles embed.FS

func frontendFile(c fiber.Ctx, name string) error {
	name = path.Clean(strings.TrimPrefix(name, "/"))
	if name == "." || strings.HasPrefix(name, "../") || name == ".." || strings.HasPrefix(name, "/") {
		return c.SendStatus(fiber.StatusNotFound)
	}
	data, err := frontendFiles.ReadFile("frontend/dist/" + name)
	if err != nil {
		return c.SendStatus(fiber.StatusNotFound)
	}
	if contentType := mime.TypeByExtension(path.Ext(name)); contentType != "" {
		c.Set(fiber.HeaderContentType, contentType)
	}
	return c.Send(data)
}

// Vite assets are built explicitly with pnpm. Unknown API paths stay 404 and
// never receive an HTML shell masquerading as a successful API response.
func mountFrontend(app *fiber.App) {
	app.Use(func(c fiber.Ctx) error {
		for _, prefix := range []string{"/api/", "/auth/", "/billing/", "/.well-known/", "/oidc/"} {
			if strings.HasPrefix(c.Path(), prefix) {
				return c.SendStatus(404)
			}
		}
		return c.Next()
	})
	app.Get("/assets/*", func(c fiber.Ctx) error {
		c.Set("Cache-Control", "public,max-age=31536000,immutable")
		return frontendFile(c, "assets/"+c.Params("*"))
	})
	app.Get("/*", func(c fiber.Ctx) error {
		for _, prefix := range []string{"/api/", "/auth/", "/billing/", "/.well-known/", "/oidc/"} {
			if strings.HasPrefix(c.Path(), prefix) {
				return c.SendStatus(404)
			}
		}
		c.Set("Cache-Control", "no-store")
		return frontendFile(c, "index.html")
	})
}

// publicConfiguration exposes OpenRails's browser-safe PSP projection.
func publicConfiguration(b *billingService, countryHeader string) fiber.Handler {
	return func(c fiber.Ctx) error {
		// Only an operator-named edge header is trusted for the buyer's country.
		country := ""
		if countryHeader != "" {
			if value := strings.ToUpper(strings.TrimSpace(c.Get(countryHeader))); len(value) == 2 && value != "XX" && value != "T1" {
				country = value
			}
		}
		psps := []billing.CheckoutPSPConfig{}
		config, err := b.client.GetCheckoutConfig(c.Context(), billing.GetCheckoutConfigParams{})
		if err == nil {
			psps = config.PSPs
		}
		c.Set("Cache-Control", "no-store")
		return c.JSON(fiber.Map{"billing_available": err == nil, "psps": psps, "country": country})
	}
}
